import React from "react";
import { Container, Row, Col } from "react-bootstrap";
import bioTest from "../data/bioTest";

export default function Bio() {
  const text = bioTest || "";

  const bgStyle = {
    position: "absolute",
    inset: 0,
    backgroundImage: 'url("/img/bg-img/bio-background-image.png")',
    backgroundSize: "cover",
    backgroundPosition: "center",
    opacity: 1,
    zIndex: 0,
  };
  const sectionInnerStyle = {
    position: "relative",
    zIndex: 1,
  };

  return (
    <section
      id="bio"
      className="bio-area section-padding-100"
      style={{ position: "relative" }}
    >
      <div aria-hidden="true" style={bgStyle} />
      <Container style={sectionInnerStyle}>
        <Row className="align-items-center">
          <Col md={5} lg={4}>
            <div className="bio-thumb text-center mb-3">
              <img
                src="img/bg-img/bio-image.jpg"
                alt="Bio"
                className="img-fluid rounded"
                loading="lazy"
              />
            </div>
          </Col>
          <Col md={7} lg={8}>
            <div className="bio-content bg-white p-3 rounded">
              <div
                className="bio-markup"
                dangerouslySetInnerHTML={{
                  __html: text || "<p>Bio loading...</p>",
                }}
              />
            </div>
          </Col>
        </Row>
      </Container>
    </section>
  );
}
